#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: deploy Patch to Google Cloud Run (DEPLOY.md, #45).
# Run from the repo root: scripts/deploy-wizard.sh
# Remembers its plain answers (project id, billing account, time zone) in deploy/cloudrun/wizard.env (git-ignored).
# Never writes a secret to a file: keys go from a hidden prompt (or backend/.env) straight into Secret Manager.
# Safe to re-run: each step checks what already exists and skips it.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=12

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
ENV_FILE="deploy/cloudrun/wizard.env"
LOCAL_ENV="backend/.env"
REGION=us-central1
SERVICE=patch

# local_value KEY: KEY's value in backend/.env (empty if unset). Read here, never printed.
local_value() {
  [[ -f "$LOCAL_ENV" ]] || return 0
  local line; line=$(grep -E "^${1}=" "$LOCAL_ENV" | tail -n1) || return 0
  printf '%s' "${line#*=}"
}

# run "what it does" cmd args...: shows the command, asks, runs it. On failure: retry, skip or stop.
run() {
  local what="$1"; shift
  printf '\n  %s%s%s\n  %s$ %s%s\n' "$BOLD" "$what" "$RESET" "$DIM" "$*" "$RESET"
  confirm "Run it?" || { note "skipped"; SKIPPED+=("$what"); return 0; }
  while ! "$@"; do
    warn "That failed. Read the message above. DEPLOY.md has the same step by hand."
    if confirm "Try again?"; then continue; fi
    if confirm "Skip it and carry on?"; then SKIPPED+=("$what"); return 0; fi
    printf '\n  Stopped. Fix it, then run scripts/deploy-wizard.sh again: it skips what is done.\n\n'; exit 1
  done
  printf '  %s✓ done%s\n' "$GREEN" "$RESET"
}

# exists cmd args...: true when the describe command finds the thing (output hidden)
exists() { "$@" >/dev/null 2>&1; }

secret_exists() { exists gcloud secrets describe "$1" --project="$PROJECT_ID"; }

# put_secret NAME VALUE: creates the secret (or adds a version) from stdin and lets the service read it
put_secret() {
  local name="$1" value="$2"
  if secret_exists "$name"; then
    printf '%s' "$value" | gcloud secrets versions add "$name" --project="$PROJECT_ID" --data-file=- >/dev/null
  else
    printf '%s' "$value" | gcloud secrets create "$name" --project="$PROJECT_ID" --replication-policy=automatic \
      --data-file=- >/dev/null
  fi
  gcloud secrets add-iam-policy-binding "$name" --project="$PROJECT_ID" --member="serviceAccount:$SA" \
    --role=roles/secretmanager.secretAccessor >/dev/null
  printf '  %s✓ secret%s %s stored, readable by the service\n' "$GREEN" "$RESET" "$name"
}

# offer_secret NAME LOCAL_KEY "label" optional|required: from backend/.env, or typed, or skipped
offer_secret() {
  local name="$1" key="$2" label="$3" need="$4" value from_env
  if secret_exists "$name"; then
    say "$label: already in Secret Manager ($name)."
    confirm "Replace it with a new value?" || return 0
  fi
  from_env=$(local_value "$key")
  if [[ -n "$from_env" ]] && confirm "Use the $label from backend/.env ($key)?"; then
    put_secret "$name" "$from_env"; return 0
  fi
  if [[ "$need" == optional ]] && ! confirm "Add a $label?"; then note "no $label: skipped"; return 0; fi
  ask_secret value "Paste the $label (hidden):"
  [[ -n "$value" ]] || { warn "empty: skipped"; return 0; }
  put_secret "$name" "$value"
  value=""
}

banner "Deploy Patch to Google Cloud Run"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools on this computer"
say "You need three tools: gcloud (Google Cloud's command line), docker and uv."
for tool in docker uv; do
  if command -v "$tool" >/dev/null 2>&1; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$tool"
  else warn "$tool is missing: install it, then run this again."; exit 1; fi
done
while ! command -v gcloud >/dev/null 2>&1; do
  warn "gcloud is missing."
  say "Your /usr is read-only (Fedora Atomic), so install it in your home folder, no root needed:"
  open_url "https://cloud.google.com/sdk/docs/install#linux"
  step "In another terminal, run Google's installer (it asks where to install: your home folder is fine):"
  note "  curl https://sdk.cloud.google.com | bash"
  step "Let it add gcloud to your PATH, then open a NEW terminal and run scripts/deploy-wizard.sh again."
  exit 0
done
printf '  %s✓%s gcloud %s\n' "$GREEN" "$RESET" "$(gcloud version 2>/dev/null | head -n1)"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Google Cloud"
ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null || true)
if [[ -n "$ACCOUNT" ]]; then
  say "Signed in as $ACCOUNT."
  confirm "Use this account?" || run "Sign in with another Google account (opens your browser)" gcloud auth login
else
  say "gcloud opens your browser: pick your Google account and allow access."
  run "Sign in (opens your browser)" gcloud auth login
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Name the project"
say "A Google Cloud project holds everything Patch uses. Its id is permanent and must be unique worldwide:"
note "6 to 30 characters, lower-case letters, digits and hyphens, starting with a letter. E.g. patch-deryk-tc"
while true; do
  ask PROJECT_ID "Project id:"
  [[ "$PROJECT_ID" =~ ^[a-z][a-z0-9-]{4,28}[a-z0-9]$ ]] && break
  warn "Not a valid project id. Try again."
done
write_env PROJECT_ID "$PROJECT_ID"
SA="patch-run@$PROJECT_ID.iam.gserviceaccount.com"
BUCKET="$PROJECT_ID-state"
IMAGE="$REGION-docker.pkg.dev/$PROJECT_ID/patch/patch"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the project and link billing"
if exists gcloud projects describe "$PROJECT_ID"; then
  say "Project $PROJECT_ID already exists."
else
  run "Create the project" gcloud projects create "$PROJECT_ID" --name="Patch"
fi
gcloud config set project "$PROJECT_ID" >/dev/null 2>&1 || true
say "Free-tier use still needs a billing account linked (a card). Nothing is charged inside the free tiers."
ACCOUNTS=$(gcloud billing accounts list --format='value(name,displayName)' --filter=open=true 2>/dev/null || true)
if [[ -z "$ACCOUNTS" ]]; then
  say "You have no billing account yet. Create one in the console (Billing → Create account), then come back."
  open_url "https://console.cloud.google.com/billing/create"
  pause "Press Enter once the billing account exists"
  ACCOUNTS=$(gcloud billing accounts list --format='value(name,displayName)' --filter=open=true 2>/dev/null || true)
fi
if [[ -n "$ACCOUNTS" ]]; then
  say "Your open billing accounts (the ID first, then its name):"
  printf '%s\n' "$ACCOUNTS" | sed 's#^billingAccounts/##; s/^/    /'
else
  warn "No open billing account found yet. Its ID is also on https://console.cloud.google.com/billing"
fi
note "The ID looks like 01A2B3-C4D5E6-F7G8H9: three groups of six, not the account's name."
if [[ "$(printf '%s\n' "$ACCOUNTS" | grep -c .)" == 1 && -z "$(_existing BILLING_ACCOUNT || true)" ]]; then
  write_env BILLING_ACCOUNT "$(printf '%s' "$ACCOUNTS" | cut -f1 | sed 's#^billingAccounts/##')"
  say "You have one billing account: press Enter to use it."
fi
while true; do
  ask BILLING_ACCOUNT "Billing account ID:"
  BILLING_ACCOUNT="${BILLING_ACCOUNT#billingAccounts/}"
  [[ "$BILLING_ACCOUNT" =~ ^[A-Z0-9]{6}-[A-Z0-9]{6}-[A-Z0-9]{6}$ ]] && break
  warn "That isn't a billing account ID (like 01A2B3-C4D5E6-F7G8H9). Try again."
done
write_env BILLING_ACCOUNT "$BILLING_ACCOUNT"
LINKED=$(gcloud billing projects describe "$PROJECT_ID" --format='value(billingEnabled)' 2>/dev/null || true)
if [[ "$LINKED" == "True" ]]; then say "Billing is already linked."
else run "Link billing to the project" gcloud billing projects link "$PROJECT_ID" --billing-account="$BILLING_ACCOUNT"; fi
PROJECT_NUMBER=$(gcloud projects describe "$PROJECT_ID" --format='value(projectNumber)')
write_env PROJECT_NUMBER "$PROJECT_NUMBER"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Turn on the services, and a \$1 budget alert"
say "Cloud Run, the image registry, Secret Manager, Scheduler, Storage and Budgets. This can take a minute."
run "Enable the services" gcloud services enable run.googleapis.com artifactregistry.googleapis.com \
  secretmanager.googleapis.com cloudscheduler.googleapis.com storage.googleapis.com billingbudgets.googleapis.com
if gcloud billing budgets list --billing-account="$BILLING_ACCOUNT" --format='value(displayName)' 2>/dev/null \
    | grep -qx "Patch"; then
  say "The \"Patch\" budget alert already exists."
else
  say "The budget emails you at 50 cents and at \$1. It only alerts; it never stops anything."
  run "Create the budget alert" gcloud billing budgets create --billing-account="$BILLING_ACCOUNT" \
    --display-name="Patch" --budget-amount=1USD --threshold-rule=percent=0.5 --threshold-rule=percent=1.0
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The service account and the bucket"
say "Patch runs as its own account, allowed only its bucket and its secrets."
if exists gcloud iam service-accounts describe "$SA"; then say "Service account patch-run exists."
else run "Create the service account" gcloud iam service-accounts create patch-run --display-name="Patch on Cloud Run"; fi
say "The bucket holds everyone's state and the live CVE data (it replaces backend/data/)."
if exists gcloud storage buckets describe "gs://$BUCKET"; then say "Bucket gs://$BUCKET exists."
else run "Create the bucket" gcloud storage buckets create "gs://$BUCKET" --location="$REGION" \
  --uniform-bucket-level-access --public-access-prevention; fi
run "Let the service read and write the bucket" gcloud storage buckets add-iam-policy-binding "gs://$BUCKET" \
  --member="serviceAccount:$SA" --role=roles/storage.objectUser
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The secrets"
say "Each key goes straight into Secret Manager: never into a file, the image or the repo."
warn "Best: an OpenRouter key made for this deploy, with a spending cap set on openrouter.ai."
offer_secret openrouter-api-key OPENROUTER_API_KEY "OpenRouter key" required
if secret_exists scheduler-secret; then say "Scheduler secret exists."
else put_secret scheduler-secret "$(openssl rand -hex 32)"; fi
offer_secret clerk-secret-key CLERK_SECRET_KEY "Clerk secret key (names on the Requests card)" optional
offer_secret ntfy-topic NTFY_TOPIC "ntfy topic (alerts on your phone)" optional
offer_secret ntfy-token NTFY_TOKEN "ntfy access token" optional
offer_secret tavily-api-key TAVILY_API_KEY "Tavily key (web research)" optional
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Build the search index and the image"
say "The image carries the search index, built with OpenRouter's embedder (well under a cent)."
note "This takes several minutes. The key is only used for the build here, never stored in the image."
ask TAG "Image tag (Enter for v1 the first time; then v2, v3...):"
TAG="${TAG:-v1}"
write_env TAG "$TAG"
if confirm "Build the index now?"; then
  key=$(local_value OPENROUTER_API_KEY)
  if [[ -z "$key" ]] || ! confirm "Use the OpenRouter key from backend/.env for the build?"; then
    ask_secret key "OpenRouter key for the build (hidden):"
  fi
  rm -rf backend/data/index-image
  (cd backend && OPENROUTER_API_KEY="$key" EMBEDDER=openrouter EMBED_MODEL= INDEX_PATH=data/index-image \
     uv run python -m app.rag.build_index) || { warn "The index build failed: see above."; exit 1; }
  key=""
  printf '  %s✓ index built%s\n' "$GREEN" "$RESET"
fi
run "Build the image" docker build --build-arg EMBEDDER=openrouter -t "$IMAGE:$TAG" .
if ! exists gcloud artifacts repositories describe patch --location="$REGION"; then
  run "Create the image registry" gcloud artifacts repositories create patch --repository-format=docker \
    --location="$REGION"
fi
run "Let docker push to it" gcloud auth configure-docker "$REGION-docker.pkg.dev" --quiet
run "Push the image (about 1 GB the first time)" docker push "$IMAGE:$TAG"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "The service's settings (env.yaml)"
URL="https://$SERVICE-$PROJECT_NUMBER.$REGION.run.app"
say "Patch's address will be: $URL"
ask ALERT_TZ "Time zone for quiet hours (e.g. Europe/Berlin):"
write_env ALERT_TZ "$ALERT_TZ"
PK=$(local_value CLERK_PUBLISHABLE_KEY); JWT=$(local_value CLERK_JWT_KEY); OWNER_ID=$(local_value OWNER)
[[ -n "$PK" && -n "$JWT" && -n "$OWNER_ID" ]] || { warn "backend/.env lacks CLERK_PUBLISHABLE_KEY, CLERK_JWT_KEY or OWNER."; exit 1; }
JWT="${JWT#\"}"; JWT="${JWT%\"}"
say "Using your local Clerk instance (publishable key, JWT key) and your user id from backend/.env."
if [[ -f deploy/cloudrun/env.yaml ]] && ! confirm "deploy/cloudrun/env.yaml exists. Write it again?"; then
  note "kept the existing env.yaml"
else
  cat > deploy/cloudrun/env.yaml <<EOF
# Written by scripts/deploy-wizard.sh from env.example.yaml and backend/.env. Git-ignored. Nothing here is secret.
LLM_PROVIDER: openrouter
OPENROUTER_MODEL: anthropic/claude-haiku-5.5
DATA_MODE: live
FEEDS: real
STORE: gcs
GCS_BUCKET: $BUCKET
AUTH: "on"
CLERK_PUBLISHABLE_KEY: $PK
CLERK_JWT_KEY: "$JWT"
OWNER: $OWNER_ID
AUTH_ALLOWED_ORIGINS: $URL
APP_URL: $URL
CORS_ORIGINS: $URL
DEV_PANEL: "true"
ALERT_TZ: $ALERT_TZ
EOF
  printf '  %s✓ wrote%s deploy/cloudrun/env.yaml\n' "$GREEN" "$RESET"
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Deploy"
SECRETS="OPENROUTER_API_KEY=openrouter-api-key:latest,SCHEDULER_SECRET=scheduler-secret:latest"
secret_exists clerk-secret-key && SECRETS+=",CLERK_SECRET_KEY=clerk-secret-key:latest"
secret_exists ntfy-topic       && SECRETS+=",NTFY_TOPIC=ntfy-topic:latest"
secret_exists ntfy-token       && SECRETS+=",NTFY_TOKEN=ntfy-token:latest"
secret_exists tavily-api-key   && SECRETS+=",TAVILY_API_KEY=tavily-api-key:latest"
say "One container, sleeping when unused (min 0), never more than one (max 1: required, see DEPLOY.md)."
run "Deploy the service" gcloud run deploy "$SERVICE" --image="$IMAGE:$TAG" --region="$REGION" \
  --service-account="$SA" --allow-unauthenticated --min-instances=0 --max-instances=1 --memory=1Gi --cpu=1 \
  --cpu-boost --timeout=900 --env-vars-file=deploy/cloudrun/env.yaml --set-secrets="$SECRETS"
say "Checking that $URL answers (the first answer can take 10-30 s: it starts the container)..."
if curl -fsS --max-time 90 -o /dev/null "$URL/api/health"; then
  printf '  %s✓%s Patch answers at %s\n' "$GREEN" "$RESET" "$URL"
else
  warn "$URL/api/health didn't answer."
  say "Cloud Run's own record of the address: $(gcloud run services describe "$SERVICE" --region="$REGION" --format='value(status.url)' 2>/dev/null || echo unknown)"
  say "If that differs, put it in AUTH_ALLOWED_ORIGINS, APP_URL and CORS_ORIGINS in deploy/cloudrun/env.yaml and re-run."
  say "Otherwise read the log (below) and tell Claude: it's a DEPLOY.md fix."
fi
note "If it doesn't start, the log says why:"
note "  gcloud logging read 'resource.type=\"cloud_run_revision\" AND resource.labels.service_name=\"patch\"' --limit=50 --freshness=1h"
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Sign in on the live app"
open_url "$URL"
step "You should see Patch's landing page. Press Sign in and sign in as yourself."
step "Expected: \"Opening Patch\", then the dashboard (with Clerk's \"Development mode\" badge)."
if ! confirm "Did signing in work?"; then
  say "Then Clerk's development instance probably refuses this address. We add it with Clerk's API."
  key=$(local_value CLERK_SECRET_KEY)
  if [[ -z "$key" ]] || ! confirm "Use the Clerk secret key from backend/.env?"; then
    ask_secret key "Clerk secret key (hidden, used once):"
  fi
  say "Calls Clerk's API: PATCH /v1/instance with allowed_origins [$URL] (the key isn't shown)."
  if confirm "Run it?"; then
    curl -fsS -X PATCH https://api.clerk.com/v1/instance -H "Authorization: Bearer $key" \
      -H "Content-Type: application/json" -d "{\"allowed_origins\": [\"$URL\"]}" >/dev/null \
      && printf '  %s✓ done%s\n' "$GREEN" "$RESET" || warn "Clerk refused it: see above."
  fi
  key=""
  step "Reload the page and sign in again."
  confirm "Does it work now?" || { warn "Stop here and tell Claude what the page shows."; exit 1; }
fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "The hourly refresh, and the checks"
say "Cloud Scheduler knocks every hour; Patch refreshes only when your Settings schedule is due."
if exists gcloud scheduler jobs describe patch-refresh --location="$REGION"; then
  say "The job patch-refresh exists."
else
  say "Creates job patch-refresh: POST $URL/api/refresh/scheduled every hour, with the scheduler secret"
  say "in the X-Scheduler-Secret header (read from Secret Manager, not shown)."
  if confirm "Run it?"; then
    secret=$(gcloud secrets versions access latest --secret=scheduler-secret)
    gcloud scheduler jobs create http patch-refresh --location="$REGION" --schedule="0 * * * *" --time-zone=UTC \
      --uri="$URL/api/refresh/scheduled" --http-method=POST --headers="X-Scheduler-Secret=$secret" \
      --attempt-deadline=600s >/dev/null && printf '  %s✓ done%s\n' "$GREEN" "$RESET" \
      || { secret=""; warn "That failed: see above. Re-run the wizard to try again."; exit 1; }
    secret=""
  else
    SKIPPED+=("the hourly Cloud Scheduler job")
  fi
fi
run "Run one tick now, to check" gcloud scheduler jobs run patch-refresh --location="$REGION"
say "Now check, on $URL (DEPLOY.md step 9):"
step "Settings → Refresh runs shows the tick (trigger \"schedule\")."
step "Dashboard → Check now runs and says what it found."
step "A second account asks for access; you get the alert, approve it, and they see their own watchlist."
step "After 15 idle minutes, open the app and time the first page (the cold start)."
note "Tell Claude the results and anything that failed: they go into STATUS.md and DEPLOY.md, then #45 closes."
pause "Press Enter to finish"

finish
